//! Generated protobuf types for the Anytype wire protocol.
//!
//! Types are generated by buf + protoc-gen-prost from shared proto/ source.
//! No gRPC service stubs are generated: Anytype uses DRPC transport, not
//! standard gRPC, so the prost message types are all the crate needs for
//! serialization/deserialization.

#![allow(non_snake_case)]

/// SpaceSync protocol types - HeadSync, ObjectSyncStream.
pub mod spacesync {
    include!("generated/spacesync/spacesync.rs");
}

/// Coordinator protocol types - SpaceSign, NetworkConfiguration.
pub mod coordinator {
    include!("generated/coordinator/coordinator.rs");
}

/// Consensus protocol types - LogAdd, RecordAdd.
pub mod consensus {
    include!("generated/consensus_proto/consensusProto.rs");
}

/// ACL record types - AclRoot, AclAccountInvite.
pub mod aclrecord {
    include!("generated/aclrecord/aclrecord.rs");
}

/// Tree change types - RootChange, TreeChange.
pub mod treechange {
    include!("generated/treechange/treechange.rs");
}

/// File sync types - BlockPush, BlockGet.
pub mod filesync {
    include!("generated/filesync/filesync.rs");
}

/// Handshake protocol types - Credentials, Ack.
pub mod handshake {
    include!("generated/any_handshake/anyHandshake.rs");
}

/// Crypto types - KeyType enum.
pub mod crypto {
    include!("generated/crypto/crypto.rs");
}

/// Block model types - SmartBlockSnapshotBase, Block, Relation.
#[allow(clippy::empty_docs, clippy::doc_lazy_continuation)]
pub mod models {
    include!("generated/anytype/model/anytype.model.rs");
}
